def msort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    l = msort(a[:mid])
    r = msort(a[mid:])
    out = []
    i = j = 0
    while i < len(l) and j < len(r):
        if l[i] <= r[j]:
            out.append(l[i])
            i += 1
        else:
            out.append(r[j])
            j += 1
    while i < len(l):
        out.append(l[i])
        i += 1
    while j < len(r):
        out.append(r[j])
        j += 1
    return out
print(msort([5, 2, 8, 1, 9, 3, 3, 7]), msort([]), msort([1]))

def sift(a, n, i):
    while True:
        big = i
        l = 2 * i + 1
        r = 2 * i + 2
        if l < n and a[l] > a[big]:
            big = l
        if r < n and a[r] > a[big]:
            big = r
        if big == i:
            return
        a[i], a[big] = a[big], a[i]
        i = big
def hsort(a):
    h = a[:]
    n = len(h)
    for i in range(n // 2 - 1, -1, -1):
        sift(h, n, i)
    for end in range(n - 1, 0, -1):
        h[0], h[end] = h[end], h[0]
        sift(h, end, 0)
    return h
print(hsort([9, 4, 7, 1, 8, 2, 6, 3, 5]), hsort([1]), hsort([]))

def bsearch(a, t, lo, hi, cnt):
    if lo > hi:
        return -1, cnt
    mid = (lo + hi) // 2
    if a[mid] == t:
        return mid, cnt + 1
    if a[mid] < t:
        return bsearch(a, t, mid + 1, hi, cnt + 1)
    return bsearch(a, t, lo, mid - 1, cnt + 1)
