def lcs(a, b):
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]
print(lcs('ABCBDAB', 'BDCABA'), lcs('', 'abc'), lcs('xyz', 'xyz'))

def knap(ws, vs, cap):
    n = len(ws)
    dp = [[0] * (cap + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for c in range(cap + 1):
            dp[i][c] = dp[i - 1][c]
            if ws[i - 1] <= c:
                take = dp[i - 1][c - ws[i - 1]] + vs[i - 1]
                if take > dp[i][c]:
                    dp[i][c] = take
    return dp[n][cap]
