# Recursion
def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)
print(fact(6), fib(10), gcd(48, 18))
print(fact(3) + fib(6))

